-- Migration: 075_achievement_conversion_and_reward_settlement.sql
-- 成果转化登记、审批、合同收益分配，以及绩效奖励发放凭证和财务回写闭环。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研成果转化" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "成果类型" integer NOT NULL,
    "成果编号" integer NOT NULL,
    "转化名称" varchar(300) NOT NULL,
    "转化方式" varchar(30) NOT NULL DEFAULT '技术转让',
    "合作单位" varchar(300),
    "合同编号" varchar(100),
    "合同签署日期" date,
    "合同金额" numeric(14,2) NOT NULL DEFAULT 0,
    "申请说明" varchar(4000),
    "状态" varchar(20) NOT NULL DEFAULT '待审批',
    "审批意见" varchar(4000),
    "申请人编号" integer NOT NULL,
    "审批人编号" integer,
    "审批时间" timestamp without time zone,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果转化" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研成果转化_类型" CHECK ("成果类型" BETWEEN 1 AND 4),
    CONSTRAINT "ck_科研成果转化_方式" CHECK ("转化方式" IN ('技术转让','许可使用','作价入股','合作开发','其他')),
    CONSTRAINT "ck_科研成果转化_金额" CHECK ("合同金额" >= 0),
    CONSTRAINT "ck_科研成果转化_状态" CHECK ("状态" IN ('草稿','待审批','已批准','执行中','已完成','已驳回','已终止'))
);
CREATE INDEX IF NOT EXISTS "ix_科研成果转化_成果" ON "科研成果转化" ("成果类型", "成果编号", "状态");
CREATE INDEX IF NOT EXISTS "ix_科研成果转化_申请人" ON "科研成果转化" ("申请人编号", "状态");
CREATE UNIQUE INDEX IF NOT EXISTS "uq_科研成果转化_合同" ON "科研成果转化" ("合同编号") WHERE "合同编号" IS NOT NULL;

CREATE TABLE IF NOT EXISTS "科研成果转化收益" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "转化编号" bigint NOT NULL REFERENCES "科研成果转化"("编号") ON DELETE CASCADE,
    "收益类型" varchar(30) NOT NULL DEFAULT '合同款',
    "计划金额" numeric(14,2) NOT NULL DEFAULT 0,
    "实际金额" numeric(14,2) NOT NULL DEFAULT 0,
    "收款日期" date,
    "收款凭证号" varchar(100),
    "分配状态" varchar(20) NOT NULL DEFAULT '待分配',
    "备注" varchar(2000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果转化收益" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研成果转化收益_类型" CHECK ("收益类型" IN ('合同款','许可费','分成','其他')),
    CONSTRAINT "ck_科研成果转化收益_金额" CHECK ("计划金额" >= 0 AND "实际金额" >= 0),
    CONSTRAINT "ck_科研成果转化收益_状态" CHECK ("分配状态" IN ('待分配','部分分配','已分配'))
);
CREATE INDEX IF NOT EXISTS "ix_科研成果转化收益_转化" ON "科研成果转化收益" ("转化编号", "分配状态");

CREATE TABLE IF NOT EXISTS "科研成果转化收益分配" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "收益编号" bigint NOT NULL REFERENCES "科研成果转化收益"("编号") ON DELETE CASCADE,
    "人员编号" integer NOT NULL REFERENCES "人员"("编号"),
    "分配比例" numeric(8,5) NOT NULL DEFAULT 0,
    "分配金额" numeric(14,2) NOT NULL DEFAULT 0,
    "财务回写状态" varchar(20) NOT NULL DEFAULT '待回写',
    "财务凭证号" varchar(100),
    "财务回写说明" varchar(1000),
    "财务回写时间" timestamp without time zone,
    "备注" varchar(1000),
    "建立人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研成果转化收益分配" PRIMARY KEY ("编号"),
    CONSTRAINT "ck_科研成果转化收益分配_比例" CHECK ("分配比例" >= 0 AND "分配比例" <= 1),
    CONSTRAINT "ck_科研成果转化收益分配_金额" CHECK ("分配金额" >= 0),
    CONSTRAINT "ck_科研成果转化收益分配_财务状态" CHECK ("财务回写状态" IN ('待回写','已回写','回写失败'))
);
CREATE UNIQUE INDEX IF NOT EXISTS "uq_科研成果转化收益分配_人员" ON "科研成果转化收益分配" ("收益编号", "人员编号");
CREATE INDEX IF NOT EXISTS "ix_科研成果转化收益分配_财务" ON "科研成果转化收益分配" ("财务回写状态", "财务回写时间");

ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "发放凭证号" varchar(100);
ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "财务回写状态" varchar(20) NOT NULL DEFAULT '待回写';
ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "财务凭证号" varchar(100);
ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "财务回写说明" varchar(1000);
ALTER TABLE "科研评价奖励" ADD COLUMN IF NOT EXISTS "财务回写时间" timestamp without time zone;
ALTER TABLE "科研评价奖励" DROP CONSTRAINT IF EXISTS "ck_科研评价奖励_财务状态";
ALTER TABLE "科研评价奖励" ADD CONSTRAINT "ck_科研评价奖励_财务状态" CHECK ("财务回写状态" IN ('待回写','已回写','回写失败'));
CREATE INDEX IF NOT EXISTS "ix_科研评价奖励_财务" ON "科研评价奖励" ("财务回写状态", "发放日期");

UPDATE "系统迁移版本"
   SET "版本" = 75,
       "脚本" = '075_achievement_conversion_and_reward_settlement.sql',
       "检查摘要" = '新增成果转化审批、合同收益分配、奖励发放凭证和财务回写状态',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;
COMMIT;
